namespace Fanex.Age.UI.Forecast
{
    using System;
    using System.Collections.Generic;
    using System.Data;
    using System.Text;
    using System.Web.UI;
    using Alpha.Web.Helpers;
    using Fanex.Age.UI.Components;
    using Fanex.Razorbill.Module.Core.Services.Impl;
    using Sunplus.Agent.Model.BL.Forecast;
    using Sunplus.Agent.Model.Entities;
    using Sunplus.Agent.Utilities;
    using Fanex.Razorbill.Module.Core.Web;

    public partial class FCHDPOU_Page : Fanex.Age.UI.TplPage
    {
        #region Const
        private const String RUNNING_LEAGUES = "RunningLeague";
        private const String FC_DATA = "FCData";
        #endregion

        #region Variable
        private int _leagueId = 0;
        private bool _fullMode = true;

        #endregion

        #region Override
        /// <summary>
        /// 
        /// </summary>
        /// <param name="writer"></param>
        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable fcData = (View as Dictionary<String, DataTable>)[FC_DATA];
            FCHDPOU_Template tpl = new FCHDPOU_Template();
            tpl.DarkModeName = DarkModeHelper.GetDarkModeName(CurrentUserSession);

            // Header name
            RenderLeagueList(tpl.Content);
            //Render row content
            FCHDPOU_Content_RowContent_Block block = new FCHDPOU_Content_RowContent_Block();
            tpl.Content.RowContent.Clear();
            if (fcData != null && fcData.Rows.Count > 0)
            {
                for (int i = 0; i < fcData.Rows.Count; i++)
                {
                    DataRow dr = fcData.Rows[i];

                    block.Home = CacheRef.GetTeamName(Convert.ToInt32(dr["homeid"])) + ((bool)dr["isNeutral"] ? Resources.Lang.IsNeutral : String.Empty);
                    block.Away = CacheRef.GetTeamName(Convert.ToInt32(dr["awayid"]));

                    int liveHomeScore = Convert.ToInt32(dr["livehomescore"]);
                    int liveAwayScore = Convert.ToInt32(dr["liveawayscore"]);

                    int offsetHDP = liveHomeScore - liveAwayScore;
                    int offsetOU = liveHomeScore + liveAwayScore;

                    if (Convert.ToInt16(dr["liveindicator"]) == 1)
                    {
                        block.Time = dr["livehomescore"].ToString() + " - " + dr["liveawayscore"].ToString() + "&nbsp;&nbsp;&nbsp;&nbsp;<i><span class='text-red'>" + Resources.Lang.lblLive + "</span></i>";
                    }
                    else
                    {
                        block.Time = dr["showtime"].ToString();
                    }
                    block.MatchId = dr["matchid"].ToString();
                    //2nd
                    block.OffsetHDPMinus1 = (offsetHDP - 1).ToString();
                    block.OffsetHDP = offsetHDP.ToString();
                    block.OffsetHDPPlus1 = (offsetHDP + 1).ToString();
                    block.OffsetOU = offsetOU.ToString();
                    block.OffsetOUPlus1 = (offsetOU + 1).ToString();
                    block.OffsetOUPlus2 = (offsetOU + 2).ToString();

                    block.HDPM1 = Convert.IsDBNull(dr["WinLost_M1_HDP"]) ? "" : RedForPositiveAmount(dr["WinLost_M1_HDP"], 0);
                    block.HDPBase = Convert.IsDBNull(dr["WinLost_0_HDP"]) ? "" : RedForPositiveAmount(dr["WinLost_0_HDP"], 0);
                    block.HDPP1 = Convert.IsDBNull(dr["WinLost_1_HDP"]) ? "" : RedForPositiveAmount(dr["WinLost_1_HDP"], 0);
                    block.OUP2 = Convert.IsDBNull(dr["WinLost_2_OU"]) ? "" : RedForPositiveAmount(dr["WinLost_2_OU"], 0);
                    block.OUP1 = Convert.IsDBNull(dr["WinLost_1_OU"]) ? "" : RedForPositiveAmount(dr["WinLost_1_OU"], 0);
                    block.OUBase = Convert.IsDBNull(dr["WinLost_0_OU"]) ? "" : RedForPositiveAmount(dr["WinLost_0_OU"], 0);

                    block.HTHDPM1 = Convert.IsDBNull(dr["WinLost_M1_HTHDP"]) ? "" : RedForPositiveAmount(dr["WinLost_M1_HTHDP"], 0);
                    block.HTHDPBase = Convert.IsDBNull(dr["WinLost_0_HTHDP"]) ? "" : RedForPositiveAmount(dr["WinLost_0_HTHDP"], 0);
                    block.HTHDPP1 = Convert.IsDBNull(dr["WinLost_1_HTHDP"]) ? "" : RedForPositiveAmount(dr["WinLost_1_HTHDP"], 0);
                    block.HTOUP2 = Convert.IsDBNull(dr["WinLost_2_HTOU"]) ? "" : RedForPositiveAmount(dr["WinLost_2_HTOU"], 0);
                    block.HTOUP1 = Convert.IsDBNull(dr["WinLost_1_HTOU"]) ? "" : RedForPositiveAmount(dr["WinLost_1_HTOU"], 0);
                    block.HTOUBase = Convert.IsDBNull(dr["WinLost_0_HTOU"]) ? "" : RedForPositiveAmount(dr["WinLost_0_HTOU"], 0);

                    tpl.Content.RowContent.Append(block);
                }
                tpl.Content.NotFoundContent.Hide();
            }

            ///  old Main URL
            tpl.BetListsUrl.BetListsUrl = MicroSites.OldMainUrl("~/");
            tpl.level = LevelName(UserSession.Current.RoleId);

            if (_fullMode) writer.Write(tpl);
            else writer.Write(tpl.Content);
        }

        public override void ProcessRequest(ref System.Collections.Hashtable p)
        {
            p.AddHttpParameters(new string[] {
                "leagueid",
            }, Request);
            _fullMode = String.IsNullOrEmpty(Request["full_mode"]) ? true : Convert.ToInt32(Request["full_mode"]) > 0;
            _leagueId = Convert.ToInt32(p["leagueid"]);

        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            if (!CurrentUserSession.SubPageAccess.ViewTotalBets &&
                !Sunplus.Agent.Model.Entities.UserSession.Current.SubPageAccess.GetPermission(Sunplus.Agent.Model.Entities.PageAccessType.ViewBetLists))
            {
                return new ErrorPage_Page(Resources.Lang.strNotAccessPage);
            }

            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            Dictionary<String, DataTable> view = new Dictionary<string, DataTable>();
            ForecastBO bo = new ForecastBO(CurrentUserSession.NetSessionId);

            DataTable fcData = null;
            DataTable runningLeagues = null;
            // Get default leagueid

            runningLeagues = bo.GetFCRunningLeagues(1); //1: for Hdp/OU/Live
            if (_leagueId == 0 && runningLeagues.Rows.Count > 0)
            {
                _leagueId = Convert.ToInt32(runningLeagues.Rows[0]["leagueid"]);
            }
            if (_leagueId > 0)
            {
                fcData = bo.GetFCByLeague(_leagueId);
            }

            view.Add(RUNNING_LEAGUES, runningLeagues);
            view.Add(FC_DATA, fcData);
            return view;
        }
        #endregion

        #region Render Utility

        private string LevelName(byte roleId)
        {
            return roleId == 4 ? "super" :
                roleId == 3 ? "master" :
                "agent";
        }

        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private string RedForPositiveAmount(object amount, byte decDigits)
        {
            if ((decimal)amount > 0)
                return "<span class='text-red'>" + Formater.DecFormat(amount, decDigits) + "</span>";
            else
                return Formater.DecFormat(amount, decDigits);
        }

        private void RenderLeagueList(FCHDPOU_Content_Block content)
        {
            DataTable leagues = (View as Dictionary<String, DataTable>)[RUNNING_LEAGUES];

            if (leagues != null && leagues.Rows.Count > 0)
            {
                StringBuilder sb = new StringBuilder();
                foreach (DataRow dr in leagues.Rows)
                {
                    int leagueId = Convert.ToInt32(dr["leagueid"]);
                    String leagueName = CacheRef.GetLeagueName(leagueId);
                    if (leagueId == _leagueId)
                    {
                        sb.Append(String.Format("<option value='{0}' selected>{1}</option>", leagueId, leagueName));
                    }
                    else
                    {
                        sb.Append(String.Format("<option value='{0}'>{1}</option>", leagueId, leagueName));
                    }
                }
                content.LimitLeagueList.LeagueList = sb.ToString();
            }
            else
            {
                content.LimitLeagueList.Hide();
            }
        }
        #endregion
    }

}
